//! This program attempts to iterate through a
//! random integer of any length
//! starting from zero
//! and find the first integer that is divisble
//! by all previous integers.
//! There are 2 possible errors in this program.
//! You must find them and fix them.
//! Assume the inputs are always valid.

#include <stdio.h>
#include <stdlib.h>

int main() {

    int upperbound;
    printf("Input number of values: ");
    scanf("%d", &upperbound);

    int *numlist = malloc(sizeof(int) * upperbound);

    printf("Input numbers:\n");
    int i = 0;
    for(i = 0; i < upperbound; i++){
        scanf("%d", &numlist[i]);
    }

    int prod;
    int arrlen = sizeof(numlist) / sizeof(numlist[0]);
    for(int j = 1; j <= arrlen; j++){
        prod = prod * numlist[j];
    }

    for(i = 0; i < upperbound; i++){
        if(prod % numlist[i] != 0){
            break;
        }
    }

    if(i == upperbound){
        printf("smallest number: %d\n", prod);
    } else {
        printf("no common factor found!\n");
    }

    return 0;
