function solution(S, P, Q) {
  // Initialize prefix sums arrays for each type of nucleotide
  const A = [0];
  const C = [0];
  const G = [0];
  const T = [0];

  // Calculate prefix sums
  for (let i = 0; i < S.length; i++) {
    const currentNucleotide = S[i];
    A.push(A[i] + (currentNucleotide === 'A' ? 1 : 0));
    C.push(C[i] + (currentNucleotide === 'C' ? 1 : 0));
    G.push(G[i] + (currentNucleotide === 'G' ? 1 : 0));
    T.push(T[i] + (currentNucleotide === 'T' ? 1 : 0));
  }

  const n = P.length;
  const result = [];

  for (let i = 0; i < n; i++) {
    const start = P[i];
    const end = Q[i];

    // Check if 'A' is present in the substring
    if (A[end + 1] - A[start] > 0) {
      result.push(1);
      continue;
    }

    // Check if 'C' is present in the substring
    if (C[end + 1] - C[start] > 0) {
      result.push(2);
      continue;
    }

    // Check if 'G' is present in the substring
    if (G[end + 1] - G[start] > 0) {
      result.push(3);
      continue;
    }

    // If 'A', 'C', and 'G' are not present, check for 'T'
    result.push(4);
  }

  return result;
}

