import random

# Main function to play the number guessing game
def number_guessing_game():
    # Setting up the game parameters
    lower_limit = 1
    upper_limit = 100
    max_attempts = 7

    # Generate a random number for the player to guess
    secret_number = random.randint(lower_limit, upper_limit)

    # Introducing the game
    print("Welcome to the Number Guessing Game!")
    print(f"I'm thinking of a number between {lower_limit} and {upper_limit}.")

    # Initializing attempt counter
    attempts = 0

    # Main game loop
    while attempts < max_attempts:
        # Asking the user to guess a number
        try:
            user_guess = int(input(f"Attempt {attempts + 1}/{max_attempts}: Guess the number: "))
        except ValueError:
            print("Please enter a valid number.")
            continue

        # Checking the guess against the secret number
        if user_guess < secret_number:
            print("Your guess is too low.")
        elif user_guess > secret_number:
            print("Your guess is too high.")
        else:
            print(f"Congratulations! You guessed the number {secret_number} in {attempts + 1} attempts.")
            break

        # Incrementing the attempt counter
        attempts += 1

    # Displaying the result if the player runs out of attempts
    if attempts == max_attempts and user_guess != secret_number:
        print(f"Sorry, you've run out of attempts. The number was {secret_number}.")

# Calling the main function to start the game
number_guessing_game()
